  const monoBlack = makeSuggestion({ colorIdentity: ['B'] });
  const monoGreen = makeSuggestion({ colorIdentity: ['G'] });
  const golgari = makeSuggestion({ colorIdentity: ['B', 'G'] });
  const colorless = makeSuggestion({ colorIdentity: [] });
  const wb = makeSuggestion({ colorIdentity: ['W', 'B'] });
  const boros = makeSuggestion({ colorIdentity: ['W', 'R'] });

  const filters = { ...EMPTY_FILTERS, colors: { include: ['B'], exclude: [] } };
  const kept = applyFilters([monoBlack, monoGreen, golgari, colorless, wb, boros], filters);
  // With subset semantics for include, keeping B should keep: mono-black (B), colorless (no identity), golgari (B,G)
  // Should drop: wb (W,B has W), mono-green (G), boros (W,R)
  assert.strictEqual(kept.length, 3);
  assert.deepStrictEqual(kept[0].colorIdentity, ['B']);
  assert.deepStrictEqual(kept[1].colorIdentity, ['B', 'G']);
  assert.deepStrictEqual(kept[2].colorIdentity, []);
});

it('color include accepts colourless commanders — empty identity fits anything', () => {
  const monoBlack = makeSuggestion({ colorIdentity: ['B'] });
  const colorless = makeSuggestion({ colorIdentity: [] });

  const filters = { ...EMPTY_FILTERS, colors: { include: ['B'], exclude: [] } };
  const kept = applyFilters([monoBlack, colorless], filters);
  // colorless identity is subset of any selection, so it should pass
  assert.strictEqual(kept.length, 2);
  // Both passed: mono-black has B in selection, colorless fits everything
  assert.deepStrictEqual(kept[0].colorIdentity, ['B']);
  assert.deepStrictEqual(kept[1].colorIdentity, []);
});

