  // Expected kept: monoRed (has R which is in selection), monoGreen (has G)
  // colorless passes, abzan fails (has W, B)
  assert.strictEqual(kept.length, 3);
  assert.deepStrictEqual(kept[0].colorIdentity, ['G']);
  assert.deepStrictEqual(kept[1].colorIdentity, ['R']);
  assert.deepStrictEqual(kept[2].colorIdentity, []);
